INSERT INTO mdl_creation_request (
    tenant_id, resource_type, request_id, request_digest
) VALUES (
    #{tenantId}, #{resourceType}, #{requestId}, #{requestDigest}
)
ON CONFLICT (tenant_id, resource_type, request_id) DO NOTHING
RETURNING id

SELECT id, tenant_id, resource_type, request_id, request_digest,
       result_parent_resource_id, result_resource_id, result_resource_code,
       result_model_type, result_status, result_approval_request_id,
       result_connectivity_status, created_at, completed_at
FROM mdl_creation_request
WHERE tenant_id = #{tenantId}
  AND resource_type = #{resourceType}
  AND request_id = #{requestId}
